#include <iostream>
#include <cstdio>
#include <algorithm>
#include <cmath>
using namespace std;

const int N = 510;
const int E = N * N;

int n, l;
int x[N], y[N];
int p[E], u[E], v[E], cnt;
int f[N], t = 0;
double d[E], ans = 0;

int getf(int u) {
    return f[u] ? f[u] = getf(f[u]) : u;
}

bool cmp(int a, int b) {
    return d[a] < d[b];
}

int main() {
    cin >> n >> l;
    for (int i = 1; i <= n; i++)
        cin >> x[i] >> y[i];
    for (int i = 1; i <= n; i++)
        for (int j = i + 1; j <= n; j++) {
            int dx = x[i] - x[j], dy = y[i] - y[j];
            if (dx * dx + dy * dy > l * l)
                continue;
            cnt++;
            p[cnt] = cnt;
            u[cnt] = i;
            v[cnt] = j;
            d[cnt] = sqrt(dx * dx + dy * dy);
        }
    sort(p + 1, p + cnt + 1, cmp);
    for (int i = 1; i <= cnt; i++) {
        int pu = u[p[i]], pv = v[p[i]];
        if (getf(pu) == getf(pv))
            continue;
        t++;
        ans += d[p[i]];
        f[getf(pu)] = pv;
    }
    if (t == n - 1)
        printf("%.2lf\n", ans);
    else
        printf("Impossible\n");
    return 0;
}

#include <iostream>
using namespace std;

const int MOD = (int)1e9 + 7;

int qpow(int base, int exp) {
    if (!exp) return 1;
    if (exp & 1) return (long long)base * qpow((long long)base * base % MOD, exp >> 1) % MOD;
    return qpow((long long)base * base % MOD, exp >> 1);
}

int comb(int n, int m) {
    if (m > n) return 0;
    int ans = 1;
    for (int i = 0; i < m; ++i) {
        ans = (long long)ans * (n - i) % MOD;
        ans = (long long)ans * qpow(i + 1, MOD - 2) % MOD;
    }
    return ans;
}

int main() {
    int m, n;
    cin >> m >> n;
    cout << comb(n - 1, m - 1) << endl;
    return 0;
}
